-- Requires a privileged lab role; run only in a disposable database.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'role_grant_demo') THEN EXECUTE 'CREATE ROLE role_grant_demo NOLOGIN'; END IF; END $$;
GRANT SELECT ON TABLE customers TO role_grant_demo;
REVOKE SELECT ON TABLE customers FROM role_grant_demo;
